    53	export function isDeadlineExceeded(deadline: number | undefined): boolean {
    54		return deadline !== undefined && Date.now() >= deadline;
    55	}
    56	
    57	export function remainingDeadlineMs(deadline: number | undefined): number {
    58		return deadline === undefined
