    60			: deadline - Date.now();
    61	}
    62	
    63	export function operationSafetyForMethod(method: string): HevyOperationSafety {
    64		const normalizedMethod = method.toUpperCase();
    65		if (["GET", "HEAD", "OPTIONS"].includes(normalizedMethod)) {
    66			return "read";
    67		}
    68		if (["PUT", "DELETE"].includes(normalizedMethod)) {
    69			return "idempotent-write";
    70		}
    71		return "non-idempotent-write";
    72	}
    73	
    74	export function canRetryOperation(
    75		safety: HevyOperationSafety,
    76		phase: HevyRequestPhase,
    77	): boolean {
    78		if (safety === "non-idempotent-write") return false;
    79		return (
    80			phase === "before-dispatch" ||
    81			phase === "dispatch" ||
    82			phase === "response-headers" ||
    83			phase === "response-content" ||
    84			phase === "backoff"
    85		);
    86	}
