    88	export function commitStateFor(
    89		safety: HevyOperationSafety,
    90		phase: HevyRequestPhase,
    91		confirmed: boolean,
    92	): HevyCommitState {
    93		if (safety === "read") return confirmed ? "confirmed" : "not_sent";
    94		if (confirmed) return "confirmed";
    95		return phase === "before-dispatch" ? "not_sent" : "unknown";
