    14	const routineDiscoverySchema = {
    15		query: z.string().min(1).optional(),
    16		limit: z.coerce.number().int().min(1).max(100).default(20),
    17	} as const;
    18	
    19	type RoutineDiscoveryParams = InferToolParams<typeof routineDiscoverySchema>;
    20	
    21	async function discoverRoutines(
    22		runtime: ToolRuntime,
    23		{ query, limit }: RoutineDiscoveryParams,
    24	): Promise<CompactRoutinesResult> {
    25		const normalizedQuery = query?.toLocaleLowerCase();
    26		const routines: Routine[] = [];
    27		let page = 1;
    28		let pages = 0;
    29		let itemsScanned = 0;
    30		const client = runtime.getClient();
    31	
    32		while (routines.length < limit) {
    33			const data: GetV1Routines200 = await client.getRoutines({
    34				page,
    35				pageSize: 10,
    36			});
    37			pages = page;
    38			const pageItems = data?.routines ?? [];
    39			itemsScanned += pageItems.length;
    40			for (const routine of pageItems) {
    41				if (
    42					normalizedQuery &&
    43					!routine.title?.toLocaleLowerCase().includes(normalizedQuery)
    44				) {
    45					continue;
    46				}
    47				routines.push(routine);
    48				if (routines.length >= limit) break;
    49			}
    50	
    51			const pageCount = data?.page_count;
    52			if (
    53				typeof pageCount !== "number" ||
    54				!Number.isSafeInteger(pageCount) ||
    55				pageCount <= page
    56			) {
    57				break;
    58			}
    59			page += 1;
    60		}
    61	
    62		return {
    63			routines: routines.slice(0, limit).map(summarizeRoutine),
    64			workflow: {
    65				name: "routine-discovery",
    66				pagination: { routines: pages },
    67				cacheStatus: "not-used",
    68				itemsScanned,
    69			},
    70		};
    71	}
