    35	/** True only for a sanitized Hevy GET of a known single resource. */
    36	export function isExpectedReadNotFound(error: unknown): boolean {
    37		return (
    38			isHevyHttpError(error) &&
    39			extractErrorStatus(error) === 404 &&
    40			error.method.toUpperCase() === "GET" &&
    41			READ_RESOURCE_ENDPOINTS.has(error.endpoint)
    42		);
    43	}
    44	
    45	/** True only for an undocumented empty page after the first page. */
    46	export function isExpectedListPageNotFound(
    47		error: unknown,
    48		page: number,
    49	): boolean {
    50		return (
    51			page > 1 &&
    52			isHevyHttpError(error) &&
    53			extractErrorStatus(error) === 404 &&
    54			error.method.toUpperCase() === "GET" &&
    55			LIST_ENDPOINTS.has(error.endpoint)
    56		);
    57	}
