    59	/** Mutation/caller 404s remain MCP errors but do not create Sentry issues. */
    60	export function isExpectedMutationNotFound(error: unknown): boolean {
    61		return (
    62			isHevyHttpError(error) &&
    63			extractErrorStatus(error) === 404 &&
    64			error.method.toUpperCase() !== "GET" &&
