 24	type RecentPageResult<T> = {
 25		items: readonly T[];
 26		pages: number;
 27		itemsScanned: number;
 28	};
 29	
 30	const MILLISECONDS_PER_DAY = 24 * 60 * 60 * 1000;
 31	
 32	function parseUtcDate(value: string): number | undefined {
 33		const normalized = value.length === 10 ? `${value}T00:00:00.000Z` : value;
 34		const timestamp = Date.parse(normalized);
 35		return Number.isFinite(timestamp) ? timestamp : undefined;
 36	}
 37	
 38	async function fetchRecentPages<T>(
 39		loader: (
 40			page: number,
 41			pageSize: number,
 42		) => Promise<{ items: readonly T[]; pageCount?: number }>,
 43		pageSize: number,
 44		startDate: string,
 45		endDate: string,
 46		getDate: (item: T) => string | undefined,
 47	): Promise<RecentPageResult<T>> {
 48		const items: T[] = [];
 49		let page = 1;
 50		let itemsScanned = 0;
 51		const startTimestamp = parseUtcDate(startDate);
 52		const endTimestamp = parseUtcDate(endDate);
 53		if (startTimestamp === undefined || endTimestamp === undefined) {
 54			return { items, pages: 0, itemsScanned };
 55		}
 56		const endExclusiveTimestamp = endTimestamp + MILLISECONDS_PER_DAY;
 57	
 58		while (true) {
 59			const result = await loader(page, pageSize);
 60			itemsScanned += result.items.length;
 61			if (result.items.length === 0) break;
 62			for (const item of result.items) {
 63				const date = getDate(item);
 64				const timestamp = date === undefined ? undefined : parseUtcDate(date);
 65				if (
 66					timestamp !== undefined &&
 67					timestamp >= startTimestamp &&
 68					timestamp < endExclusiveTimestamp
 69				) {
 70					items.push(item);
 71				}
 72			}
 73	
 74			const lastDate = result.items
 75				.map(getDate)
 76				.filter((date): date is string => date !== undefined)
 77				.at(-1);
 78			const lastTimestamp =
 79				lastDate === undefined ? undefined : parseUtcDate(lastDate);
 80			if (lastTimestamp !== undefined && lastTimestamp < startTimestamp) {
 81				break;
 82			}
 83			const pageCount = result.pageCount;
 84			if (
 85				typeof pageCount !== "number" ||
 86				!Number.isSafeInteger(pageCount) ||
 87				pageCount <= page
 88			) {
 89				break;
 90			}
 91			page += 1;
 92		}
 93		return { items, pages: page, itemsScanned };
 94	}
 95	
 96	function utcDateString(date: Date): string {
 97		return date.toISOString().slice(0, 10);
 98	}
 99	
100	function getPeriod(weeks: number): {
101		startDate: string;
102		endDate: string;
103	} {
104		const end = new Date();
105		const start = new Date(end);
106		start.setUTCDate(start.getUTCDate() - weeks * 7);
107		return { startDate: utcDateString(start), endDate: utcDateString(end) };
108	}
109	
110	function durationSeconds(workout: Workout): number | undefined {
111		if (!workout.start_time || !workout.end_time) return undefined;
112		const duration =
113			new Date(workout.end_time).getTime() -
114			new Date(workout.start_time).getTime();
115		return Number.isFinite(duration) && duration >= 0
116			? Math.floor(duration / 1000)
117			: undefined;
118	}
119	
120	function compactSession(
121		workout: Workout,
122	): TrainingSummaryResult["workouts"]["sessions"][number] {
123		const exercises = workout.exercises ?? [];
124		const elapsedSeconds = durationSeconds(workout);
125		return {
126			...(workout.id ? { id: workout.id } : {}),
127			...(workout.title ? { title: workout.title } : {}),
128			...(workout.start_time ? { start_time: workout.start_time } : {}),
129			...(workout.end_time ? { end_time: workout.end_time } : {}),
130			...(elapsedSeconds === undefined
131				? {}
132				: { duration_seconds: elapsedSeconds }),
133			exercise_count: exercises.length,
134			set_count: exercises.reduce(
135				(total, exercise) => total + (exercise.sets?.length ?? 0),
136				0,
137			),
138		};
139	}
140	
141	function compactMeasurement(
142		measurement: BodyMeasurement,
143	): NonNullable<TrainingSummaryResult["body_measurements"]["latest"]> {
144		return {
145			date: measurement.date,
146			...(measurement.weight_kg == null
147				? {}
148				: { weight_kg: measurement.weight_kg }),
149			...(measurement.lean_mass_kg == null
150				? {}
151				: { lean_mass_kg: measurement.lean_mass_kg }),
152			...(measurement.fat_percent == null
153				? {}
154				: { fat_percent: measurement.fat_percent }),
155		};
156	}
