158	export async function getTrainingSummary(
159		runtime: ToolRuntime,
160		weeks: number,
161	): Promise<TrainingSummaryResult> {
162		const client = runtime.getClient();
163		const period = getPeriod(weeks);
164		const pageSize = 10;
165		const [workoutPages, measurementPages] = await Promise.all([
166			fetchRecentPages(
167				async (page, pageSize) => {
168					const data: GetV1Workouts200 = await client.getWorkouts({
169						page,
170						pageSize,
171					});
172					return { items: data?.workouts ?? [], pageCount: data?.page_count };
173				},
174				pageSize,
175				period.startDate,
176				period.endDate,
177				(workout) => workout.start_time,
178			),
179			fetchRecentPages(
180				async (page, pageSize) => {
181					const data: GetV1BodyMeasurements200 = await client.getBodyMeasurements(
182						{
183							page,
184							pageSize,
185						},
186					);
187					return {
188						items: data?.body_measurements ?? [],
189						pageCount: data?.page_count,
190					};
191				},
192				pageSize,
193				period.startDate,
194				period.endDate,
195				(measurement) => measurement.date,
196			),
197		]);
198	
199		const workouts = workoutPages.items;
200		const sessions = workouts.map(compactSession);
201		const unique_exercise_template_ids = [
202			...new Set(
203				workouts.flatMap((workout) =>
204					(workout.exercises ?? [])
205						.map((exercise) => exercise.exercise_template_id)
206						.filter((id): id is string => Boolean(id)),
207				),
208			),
209		];
210		const measurements = [...measurementPages.items].sort((a, b) =>
211			a.date.localeCompare(b.date),
212		);
213		const earliestMeasurement = measurements[0];
214		const latestMeasurement = measurements.at(-1);
215		const earliest = earliestMeasurement
216			? compactMeasurement(earliestMeasurement)
217			: undefined;
218		const latest = latestMeasurement
219			? compactMeasurement(latestMeasurement)
220			: undefined;
221		const weight_change_kg =
222			latest?.weight_kg !== undefined && earliest?.weight_kg !== undefined
223				? latest.weight_kg - earliest.weight_kg
224				: undefined;
225	
226		return {
227			period: { start_date: period.startDate, end_date: period.endDate, weeks },
228			workouts: {
229				count: workouts.length,
230				total_duration_seconds: sessions.reduce(
231					(total, session) => total + (session.duration_seconds ?? 0),
232					0,
233				),
234				exercise_count: sessions.reduce(
235					(total, session) => total + session.exercise_count,
236					0,
237				),
238				set_count: sessions.reduce(
239					(total, session) => total + session.set_count,
240					0,
241				),
242				unique_exercise_template_ids,
243				sessions,
244			},
245			body_measurements: {
246				count: measurements.length,
247				...(latest ? { latest } : {}),
248				...(earliest ? { earliest } : {}),
249				...(weight_change_kg === undefined ? {} : { weight_change_kg }),
250			},
251			workflow: {
252				name: "training-summary",
253				pagination: {
254					workouts: workoutPages.pages,
255					body_measurements: measurementPages.pages,
256				},
257				cacheStatus: "not-used",
258				itemsScanned: workoutPages.itemsScanned + measurementPages.itemsScanned,
259			},
260		};
261	}
