 27	export type ToolDefinition<
 28		TSchema extends Record<string, z.ZodTypeAny>,
 29		TResult,
 30	> = ToolDefinitionBase<TSchema, TResult> &
 31		(
 32			| {
 33					readonly kind: "read";
 34					readonly outputSchema: z.ZodRawShape;
 35			  }
 36			| {
 37					readonly kind: "write";
 38					readonly outputSchema?: never;
 39			  }
 40		);
