 42	export function registerToolDefinition(
 43		server: McpServer,
 44		runtime: ToolRuntime,
 45		definition: ToolDefinition<Record<string, z.ZodTypeAny>, unknown>,
 46	): void {
 47		const directHandler = createTypedToolHandler(
 48			definition.inputSchema,
 49			async (args, requestContext) =>
 50				respond(
 51					definition.responseContract,
 52					await definition.execute(
 53						requestContext ? runtime.forExecution(requestContext) : runtime,
 54						args,
 55					),
 56				),
 57		);
 58		const handler = runtime.createHandler(directHandler, definition.name, {
 59			feature: definition.feature,
 60			kind: definition.kind,
 61			operation: definition.operation,
 62		});
 63		const callback = handler;
 64	
 65		const inputSchema = compactJsonSchema(z.strictObject(definition.inputSchema));
 66		const config = {
 67			description: definition.description,
 68			inputSchema,
 69			annotations: definition.annotations,
 70			...(definition.kind === "read"
 71				? {
 72						outputSchema: compactJsonSchema(z.object(definition.outputSchema)),
 73					}
 74				: {}),
 75		};
 76	
 77		server.registerTool(definition.name, config, (args, context) =>
 78			callback(
 79				args,
 80				context
 81					? {
 82							signal: context.mcpReq.signal,
 83							requestId: String(context.mcpReq.id),
 84						}
 85					: undefined,
 86			),
 87		);
 88	}
