   486				if (settled) return;
   487				settled = true;
   488				signal.removeEventListener("abort", onAbort);
   489				reject(
   490					signal.reason ?? new DOMException("Operation canceled", "AbortError"),
   491				);
   492			};
   493			signal.addEventListener("abort", onAbort, { once: true });
   494			void sleep(delayMs, signal).then(
   495				() => {
   496					if (settled) return;
   497					settled = true;
   498					signal.removeEventListener("abort", onAbort);
   499					resolve();
   500				},
   501				(error) => {
   502					if (settled) return;
   503					settled = true;
   504					signal.removeEventListener("abort", onAbort);
