641	/** Execute one dispatch/response attempt and retain its safe phase state. */
642	async function executeRequestAttempt<TData>(
643		options: RequestAttemptExecutionOptions,
644	): Promise<RequestAttemptOutcome<TData>> {
645		let phase: HevyRequestPhase = "before-dispatch";
646		let responseConfirmed = false;
647		const attemptController = new AbortController();
648		const abortAttempt = () =>
649			attemptController.abort(options.executionSignal.reason);
650		options.executionSignal.addEventListener("abort", abortAttempt, {
651			once: true,
652		});
653		try {
654			const result = await runRequestObservation(
655				options.observationScope,
656				async () => {
657					const headers = new Headers({ "api-key": options.apiKey });
658					if (
659						options.normalized.data !== undefined &&
660						!(options.normalized.data instanceof FormData)
661					) {
662						headers.set("content-type", "application/json");
663					}
664					const requestInit: RequestInit = {
665						method: options.method,
666						headers,
667						redirect: "manual",
668						body:
669							options.normalized.data instanceof FormData
670								? options.normalized.data
671								: options.normalized.data === undefined
672									? undefined
673									: JSON.stringify(options.normalized.data),
674						signal: attemptController.signal,
675					};
676					let fetchPromise: Promise<Response>;
677					try {
678						const fetchImplementation = options.fetchImplementation;
679						fetchPromise = Promise.resolve(
680							fetchImplementation(options.url, requestInit),
681						);
682					} catch (error) {
683						phase = "before-dispatch";
684						throw error;
685					}
686					phase = "dispatch";
687					const response = await withTimeout(
688						fetchPromise,
689						remainingDeadlineMs(options.deadline),
690						() =>
691							attemptController.abort(
692								new DOMException("Operation timed out", "TimeoutError"),
693							),
694						attemptController.signal,
695					);
696					phase = "response-headers";
697					phase = "response-content";
698					const data = await withTimeout(
699						parseResponseData(response),
700						remainingDeadlineMs(options.deadline),
701						() =>
702							attemptController.abort(
703								new DOMException("Operation timed out", "TimeoutError"),
704							),
705						attemptController.signal,
706					);
707					if (!response.ok) {
708						throw new HevyHttpError(
709							`Hevy API request failed (HTTP ${response.status})`,
710							{
711								status: response.status,
712								statusText: response.statusText,
713								data,
714								headers: response.headers,
715								method: options.method,
716								endpoint: options.endpoint,
717								phase,
718								operationSafety: options.safety,
719								commitState: commitStateFor(options.safety, phase, false),
720								safeToRetry: false,
721							},
722						);
723					}
724					responseConfirmed = true;
725					const observation: HevyRequestObservation = {
726						method: options.method,
727						endpoint: options.endpoint,
728						status: response.status,
729						durationMs: Date.now() - options.startedAt,
730						retryCount: options.retryCount,
731						outcome: "success",
732						phase: "completed",
733						operationSafety: options.safety,
734						commitState: "confirmed",
735						safeToRetry: false,
736					};
737					finishRequestObservation(options.observationScope, observation);
738					emitRequestObservation(options.onRequestComplete, observation);
739					return {
740						data: data as TData,
741						status: response.status,
742						statusText: response.statusText,
743						headers: response.headers,
744					};
745				},
746			);
747			return { ok: true, result };
748		} catch (cause) {
749			return { ok: false, cause, phase, responseConfirmed };
750		} finally {
751			options.executionSignal.removeEventListener("abort", abortAttempt);
752		}
753	}
