   445	function oauthUnauthorizedResponse(request: Request): Response {
   446		const url = new URL(request.url);
   447		const resourceMetadataUrl =
   448			`${url.origin}/.well-known/oauth-protected-resource` + url.pathname;
   449		return new Response("Unauthorized", {
   450			status: 401,
   451			headers: {
   452				"WWW-Authenticate":
   453					'Bearer error="invalid_token", ' +
   454					'error_description="The Hevy API key behind this grant is no ' +
   455					'longer valid", ' +
   456					`resource_metadata="${resourceMetadataUrl}"`,
   457			},
   458		});
   459	}
   460	
   461	async function handleAuthorizedMcpRequest<Env>(
   462		request: Request,
   463		env: Env,
   464		ctx: object,
   465		dependencies: HevyOAuthDependencies<Env>,
   466	): Promise<Response> {
   467		const deadline = Date.now() + WORKER_INVOCATION_TIMEOUT_MS;
   468		const props = (ctx as { props?: Partial<HevyGrantProps> } | null | undefined)
   469			?.props;
   470		const apiKey =
   471			typeof props?.hevyApiKey === "string" ? props.hevyApiKey : null;
   472		if (!apiKey) return oauthUnauthorizedResponse(request);
   473	
   474		let validation: HevyOAuthValidation;
   475		try {
   476			validation = await dependencies.validateApiKey(
   477				apiKey,
   478				env,
   479				request.signal,
   480				deadline,
   481			);
   482		} catch (error) {
   483			return jsonValidationFailure(error, request);
   484		}
   485		if (validation === "config-error") {
   486			return jsonConfigErrorResponse();
   487		}
   488		if (validation === "invalid") return oauthUnauthorizedResponse(request);
   489		return dependencies.serveMcp(request, env, apiKey, deadline);
   490	}
   491	
   492	/**
   493	 * Build the OAuth provider that fronts the Worker when an `OAUTH_KV`
   494	 * namespace is bound. It implements OAuth 2.1 authorization code flow with
   495	 * PKCE, CIMD client metadata with DCR fallback, and RFC 8414 / RFC 9728
   496	 * discovery metadata for remote MCP clients including ChatGPT.
   497	 */
   498	export function createHevyOAuthProvider<Env extends object>(
   499		dependencies: HevyOAuthDependencies<Env>,
   500	): HevyOAuthWorker<Env> {
   501		const provider = new OAuthProvider({
   502			apiRoute: MCP_PATH,
   503			apiHandler: {
   504				fetch: (request: Request, env: Env, ctx: object) =>
   505					handleAuthorizedMcpRequest(request, env, ctx, dependencies),
   506			},
   507			defaultHandler: {
   508				fetch: async (request: Request, env: Env & OAuthProviderEnv) => {
   509					const url = new URL(request.url);
   510					if (url.pathname !== AUTHORIZE_PATH) {
   511						return new Response("Not found", { status: 404 });
   512					}
   513					if (request.method === "GET") {
   514						return handleAuthorizeGet(request, env.OAUTH_PROVIDER);
   515					}
   516					if (request.method === "POST") {
   517						return handleAuthorizePost(
   518							request,
   519							env,
   520							env.OAUTH_PROVIDER,
   521							dependencies,
   522						);
   523					}
   524					return new Response("Method not allowed", {
   525						status: 405,
   526						headers: { Allow: "GET, POST" },
   527					});
   528				},
   529			},
   530			authorizeEndpoint: AUTHORIZE_PATH,
   531			tokenEndpoint: TOKEN_PATH,
   532			clientRegistrationEndpoint: REGISTER_PATH,
   533			scopesSupported: ["mcp"],
   534			accessTokenTTL: OAUTH_ACCESS_TOKEN_TTL_SECONDS,
   535			refreshTokenTTL: OAUTH_REFRESH_TOKEN_TTL_SECONDS,
   536			clientIdMetadataDocumentEnabled: true,
   537			allowPlainPKCE: false,
   538			resourceMetadata: { resource_name: "Hevy MCP Server" },
   539		});
   540		return provider as unknown as HevyOAuthWorker<Env>;
   541	}

