   130			const sessionId = getCurrentMcpSessionId();
   131			if (activeSpan) {
   132				activeSpan.addEvent("mcp.tool.failure", {
   133					"mcp.tool.name": sdkToolNameStorage.getStore() ?? "unknown",
   134					...attributes,
   135				});
