   143					"mcp.sdk.failure",
   144					{
   145						attributes: {
   146							"mcp.span.category": "protocol",
   147							"mcp.transport": transport,
   148							...(sessionId ? { "mcp.session.id": sessionId } : {}),
   149						},
   150					},
   151					(span) => {
   152						span.addEvent("mcp.tool.failure", {
   153							"mcp.tool.name": "unknown",
   154							...attributes,
   155						});
   156						captureFailure(error, { kind: "protocol", attributes, span });
   157						span.end();
   158					},
   159				);
   160			}
