    75	 * objects/strings and most generated wrappers silently ignore extra args.
    76	 */
    77	/** Canonical options-slot metadata shared by binding and table-driven tests. */
    78	export const HEVY_CLIENT_OPTION_INDEXES: Record<ClientMethod, number> = {
    79		getWorkouts: 1,
    80		getWorkout: 1,
    81		createWorkout: 1,
    82		updateWorkout: 2,
    83		getWorkoutCount: 0,
