   103	/**
   104	 * Bind one immutable control object to every curated client operation. A
   105	 * proxy keeps existing tool code source-compatible while making it impossible
   106	 * for one page of a workflow to silently lose cancellation/deadline state.
   107	 */
   108	export function bindClientExecution(
   109		client: HevyClient,
   110		control: ToolExecutionContext,
   111	): HevyClient {
   112		return new Proxy(client, {
   113			get(target, property, receiver) {
   114				const value = Reflect.get(target, property, receiver);
   115				if (typeof value !== "function") return value;
   116				const optionIndex =
   117					property in HEVY_CLIENT_OPTION_INDEXES
   118						? HEVY_CLIENT_OPTION_INDEXES[property as ClientMethod]
   119						: undefined;
   120				if (optionIndex === undefined) {
   121					return value.bind(target);
   122				}
   123				return (...args: unknown[]) => {
   124					const provided = args[optionIndex] as HevyRequestOptions | undefined;
   125					const merged: HevyRequestOptions = {
   126						...provided,
   127						...control,
   128					};
   129					args[optionIndex] = merged;
   130					return Reflect.apply(value, target, args);
   131				};
   132			},
   133		}) as HevyClient;
   134	}
