    99	export function memoizeObservationScope(
   100		scope: ToolObservationScope | void,
   101	): ToolObservationScope | undefined {
   102		if (!scope) return undefined;
   103		let finished = false;
   104		let operationPromise: Promise<unknown> | undefined;
   105		return {
   106			run<T>(operation: () => Promise<T>): Promise<T> {
   107				if (!operationPromise) {
   108					try {
   109						operationPromise = Promise.resolve(scope.run(operation));
   110					} catch (error) {
   111						operationPromise = Promise.reject(error);
   112					}
   113				}
   114				return operationPromise as Promise<T>;
   115			},
   116			finish(completion) {
   117				if (finished) return;
   118				finished = true;
   119				try {
   120					const pending = scope.finish(completion);
   121					if (pending) void pending.catch(() => undefined);
   122				} catch {
   123					// Observation must never alter MCP behavior.
   124				}
   125			},
   126		};
