  1	function scalar(value: unknown): string {
  2		if (value === null || value === undefined) return "null";
  3		if (typeof value === "object") return JSON.stringify(value);
  4		return typeof value === "string" ? value : (JSON.stringify(value) ?? "");
  5	}
  6	
  7	export function human(value: unknown): string {
  8		if (Array.isArray(value))
  9			return value.length
 10				? value.map((item) => human(item)).join("\n")
 11				: "No results.";
 12		if (!value || typeof value !== "object") return scalar(value);
 13		const record = value as Record<string, unknown>;
 14		const lines: string[] = [];
 15		for (const [key, item] of Object.entries(record)) {
 16			if (Array.isArray(item)) {
 17				lines.push(`${key}: ${item.length} item(s)`);
 18				for (const child of item.slice(0, 20)) {
 19					if (child && typeof child === "object")
 20						lines.push(
 21							`  - ${Object.entries(child as Record<string, unknown>)
 22								.map(([k, v]) => `${k}=${scalar(v)}`)
 23								.join(", ")}`,
 24						);
 25					else lines.push(`  - ${scalar(child)}`);
 26				}
 27			} else if (item && typeof item === "object") {
 28				lines.push(`${key}:`);
 29				lines.push(
 30					...human(item)
 31						.split("\n")
 32						.map((line) => `  ${line}`),
 33				);
 34			} else lines.push(`${key}: ${scalar(item)}`);
 35		}
 36		return lines.join("\n") || "No results.";
 37	}

