 11	const EXERCISE_TEMPLATE_CATALOG_CACHE_KEY = "exercise-template-catalog";
 12	const EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS = 5 * 60 * 1000;
 13	const EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE = 1;
 14	
 15	export type ExerciseTemplateCatalogRefreshReason =
 16		| "explicit-refresh"
 17		| "initial-load"
 18		| "ttl-expired";
 19	
 20	export interface ExerciseTemplateCatalogOptions {
 21		refresh?: boolean;
 22		execution?: HevyRequestOptions;
 23		onRefreshed?: (
 24			catalog: ExerciseTemplate[],
 25			reason: ExerciseTemplateCatalogRefreshReason,
 26		) => void;
 27	}
 28	
 29	export interface ExerciseTemplateCatalog {
 30		get(options?: ExerciseTemplateCatalogOptions): Promise<ExerciseTemplate[]>;
 31		reset(): void;
 32	}
 33	
 34	export function createExerciseTemplateCatalog(
 35		hevyClient: Pick<HevyClient, "getExerciseTemplates">,
 36		cacheObserver?: CacheObserver,
 37	): ExerciseTemplateCatalog {
 38		const cache = new AsyncTtlCache<string, ExerciseTemplate[]>({
 39			ttlMs: EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS,
 40			maxSize: EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE,
 41			observer: cacheObserver,
 42		});
 43	
 44		return {
 45			get(options = {}) {
 46				const reason = options.refresh
 47					? "explicit-refresh"
 48					: cache.size === 0
 49						? "initial-load"
 50						: "ttl-expired";
 51				let observationMetadata: CacheObservationMetadata | undefined;
 52				let pagesLoaded = 0;
 53				return cache.getOrFetch(
 54					EXERCISE_TEMPLATE_CATALOG_CACHE_KEY,
 55					async () => {
 56						const catalog = await fetchAllPages<ExerciseTemplate>(
 57							async (page, pageSize) => {
 58								pagesLoaded = page;
 59								const data: GetV1ExerciseTemplates200 =
 60									await hevyClient.getExerciseTemplates(
 61										{
 62											page,
 63											pageSize,
 64										},
 65										options.execution,
 66									);
 67								return {
 68									items: data?.exercise_templates ?? [],
 69									pageCount: data?.page_count,
 70								};
 71							},
 72							100,
 73						);
 74						observationMetadata = {
 75							refreshReason: reason,
 76							pageCountBucket: bucketCount(pagesLoaded),
 77							itemCountBucket: bucketCount(catalog.length),
 78						};
 79						options.onRefreshed?.(catalog, reason);
 80						return catalog;
 81					},
 82					{
 83						refresh: options.refresh,
 84						shareInFlight: options.execution === undefined,
 85						signal: options.execution?.signal,
 86						deadline: options.execution?.deadline,
 87						getObservationMetadata: () => observationMetadata,
 88					},
 89				);
 90			},
 91			reset() {
 92				cache.clear();
 93			},
 94		};
 95	}
