 68		constructor(options: AsyncCacheOptions, now: () => number = Date.now) {
 69			const { ttlMs, maxSize, observer } = options;
 70			if (ttlMs <= 0) {
 71				throw new Error("Cache ttlMs must be greater than 0.");
 72			}
 73			if (maxSize <= 0) {
 74				throw new Error("Cache maxSize must be greater than 0.");
 75			}
