 87				return this.observer?.start({ state }) ?? undefined;
 88			} catch {
 89				return undefined;
 90			}
 91		}
 92	
 93		private finishObservation(
 94			scope: CacheObservationScope | undefined,
 95			metadata?: CacheObservationMetadata,
 96		): void {
 97			try {
 98				scope?.finish(metadata);
 99			} catch {
100				// Cache observation is best-effort and cannot affect cache behavior.
101			}
102		}
