104		private async waitForCaller<T>(
105			promise: Promise<T>,
106			signal?: AbortSignal,
107			deadline?: number,
108		): Promise<T> {
109			if (signal === undefined && deadline === undefined) return promise;
110			if (signal?.aborted) {
111				throw (
112					signal.reason ?? new DOMException("Operation canceled", "AbortError")
113				);
114			}
115			if (deadline !== undefined && Date.now() >= deadline) {
116				throw new DOMException("Operation deadline exceeded", "TimeoutError");
117			}
118			return new Promise<T>((resolve, reject) => {
119				let settled = false;
120				let timer: ReturnType<typeof setTimeout> | undefined;
121				const cleanup = () => {
122					if (timer !== undefined) clearTimeout(timer);
123					signal?.removeEventListener("abort", onAbort);
124				};
125				const finish = (callback: () => void) => {
126					if (settled) return;
127					settled = true;
128					cleanup();
129					callback();
130				};
131				const onAbort = () =>
132					finish(() =>
133						reject(
134							signal?.reason ??
135								new DOMException("Operation canceled", "AbortError"),
136						),
137					);
138				if (signal !== undefined)
139					signal.addEventListener("abort", onAbort, { once: true });
140				if (deadline !== undefined) {
141					timer = setTimeout(
142						() =>
143							finish(() =>
144								reject(
145									new DOMException("Operation deadline exceeded", "TimeoutError"),
146								),
147							),
148						Math.max(0, deadline - Date.now()),
149					);
150				}
151				void promise.then(
152					(value) => finish(() => resolve(value)),
153					(error: unknown) => finish(() => reject(error)),
154				);
155			});
156		}
157	
158		async getOrFetch(
159			key: TKey,
160			fetcher: () => Promise<TValue>,
161			options: CacheGetOptions = {},
162		): Promise<TValue> {
163			const {
164				refresh = false,
165				shareInFlight = true,
166				signal,
167				deadline,
168				getObservationMetadata,
169			} = options;
170			let observationState: CacheObservationState = refresh ? "refresh" : "miss";
171	
172			if (refresh) {
173				if (shareInFlight) this.invalidate(key);
174			} else {
175				const cachedEntry = this.entries.get(key);
176				if (cachedEntry !== undefined) {
177					if (cachedEntry.expiresAt > this.now()) {
178						this.markAsRecentlyUsed(key, cachedEntry);
179						const observationScope = this.startObservation("hit");
180						this.finishObservation(observationScope);
181						return this.waitForCaller(
182							Promise.resolve(cachedEntry.value),
183							signal,
184							deadline,
185						);
186					}
187	
188					this.entries.delete(key);
189					observationState = "expired";
190				}
191	
192				const inFlightEntry = shareInFlight ? this.inFlight.get(key) : undefined;
193				if (inFlightEntry !== undefined) {
194					const observationScope = this.startObservation("inflight_wait");
195					void inFlightEntry.promise.then(
196						() => this.finishObservation(observationScope),
197						() => this.finishObservation(observationScope),
198					);
199					return this.waitForCaller(inFlightEntry.promise, signal, deadline);
200				}
201			}
202	
203			const requestId = ++this.requestCounter;
204			this.latestRequestIds.set(key, requestId);
205			const observationScope = this.startObservation(observationState);
206			const request = (async () => {
207				try {
208					const value = await fetcher();
209	
210					if (this.isCurrentRequest(key, requestId)) {
211						this.setValue(key, value);
212					}
213	
214					return value;
215				} finally {
216					let metadata: CacheObservationMetadata | undefined;
217					try {
218						metadata = getObservationMetadata?.();
219					} catch {
220						metadata = undefined;
221					}
222					this.finishObservation(observationScope, metadata);
223					const inFlightEntry = shareInFlight
224						? this.inFlight.get(key)
225						: undefined;
226					if (inFlightEntry?.requestId === requestId) {
227						this.inFlight.delete(key);
228					}
229					if (this.latestRequestIds.get(key) === requestId) {
230						this.latestRequestIds.delete(key);
231					}
232				}
233			})();
234	
235			if (shareInFlight) this.inFlight.set(key, { promise: request, requestId });
236			return this.waitForCaller(request, signal, deadline);
237		}
238	
239		invalidate(key: TKey): void {
240			this.entries.delete(key);
241			this.inFlight.delete(key);
242			this.latestRequestIds.delete(key);
243		}
244	
245		clear(): void {
246			this.entries.clear();
247			this.inFlight.clear();
248			this.latestRequestIds.clear();
249		}
250	
251		get size(): number {
252			return this.entries.size;
253		}
254	
255		private isCurrentRequest(key: TKey, requestId: number): boolean {
256			return this.latestRequestIds.get(key) === requestId;
257		}
258	
259		private markAsRecentlyUsed(key: TKey, entry: CacheEntry<TValue>): void {
260			this.entries.delete(key);
261			this.entries.set(key, entry);
262		}
263	
264		private setValue(key: TKey, value: TValue): void {
265			this.entries.delete(key);
266			this.entries.set(key, {
267				value,
268				expiresAt: this.now() + this.ttlMs,
269			});
270	
271			this.evictLeastRecentlyUsed();
272		}
273	
274		private evictLeastRecentlyUsed(): void {
275			while (this.entries.size > this.maxSize) {
276				const oldestKey = this.entries.keys().next().value;
277				if (oldestKey === undefined) {
278					return;
279				}
280	
281				this.entries.delete(oldestKey);
282			}
283		}
284	}
