403			}
404			return {};
405		}
406		return {
407			...(error.phase ? { phase: error.phase } : {}),
408			...(error.operation_safety
409				? { operation_safety: error.operation_safety }
410				: {}),
411			...(error.commit_state ? { commit_state: error.commit_state } : {}),
412			...(typeof error.safe_to_retry === "boolean"
