419	function parseSafeStackFrames(error: unknown): SafeStackFrame[] | undefined {
420		if (!(error instanceof Error) || typeof error.stack !== "string") {
421			return undefined;
422		}
423	
424		const frames: SafeStackFrame[] = [];
425		for (const frameLine of error.stack.split(/\r?\n/).slice(1)) {
426			const match =
427				/^\s{4}at (?:[^()\r\n]+ \()?([^()\s\r\n]+):(\d+):(\d+)\)?$/.exec(
428					frameLine,
429				);
430			if (!match) continue;
431			const [, rawSource, rawLine, rawColumn] = match;
432			if (!rawSource || !rawLine || !rawColumn) continue;
433			if (
434				rawSource.includes("?") ||
435				rawSource.includes("#") ||
436				(!rawSource.startsWith("/") && !rawSource.startsWith("file:///")) ||
437				!rawSource.includes(PROJECT_PATH_MARKER)
438			) {
439				continue;
440			}
441			const source = SAFE_SOURCE_SUFFIXES.find(([suffix]) =>
442				rawSource.endsWith(suffix),
443			)?.[1];
444			if (!source) continue;
445			const line = Number(rawLine);
446			const column = Number(rawColumn);
447			if (
448				!Number.isSafeInteger(line) ||
449				!Number.isSafeInteger(column) ||
450				line < 1 ||
451				column < 1 ||
452				line > MAX_STACK_POSITION ||
453				column > MAX_STACK_POSITION
454			) {
455				continue;
456			}
457			frames.push({ source, line, column });
458			if (frames.length === 3) break;
459		}
460		return frames.length > 0 ? frames : undefined;
461	}
