490	/** Resolve all bounded policy outputs used by MCP, telemetry, and reporting adapters. */
491	export function resolveErrorPolicy(
492		error: unknown,
493		defaultMessage: string,
494		notInitializedMessage?: string,
495	): ErrorPolicyResult {
496		const diagnostic = createSafeErrorDiagnostic(error);
497		const mappedMessage = getStatusErrorMessage(diagnostic.status);
498		let message =
499			mappedMessage ??
500			(diagnostic.status !== undefined
501				? `Hevy API request failed (HTTP ${diagnostic.status}).`
502				: defaultMessage);
503		let isNotInitialized = false;
504		try {
505			isNotInitialized =
506				Boolean(notInitializedMessage) &&
507				error instanceof Error &&
508				error.message === notInitializedMessage;
509		} catch {
510			isNotInitialized = false;
511		}
512		if (isNotInitialized) {
513			message = notInitializedMessage ?? defaultMessage;
514		} else if (isRetryExhausted(error)) {
515			message = getRetryExhaustedMessage(error);
516		} else if (diagnostic.status === 429) {
517			message = getRateLimitMessage(error);
518		}
519		return { type: determineErrorType(error, message), message, diagnostic };
520	}
