166	/**
167	 * Wrap an async function with standardized error handling
168	 *
169	 * @param fn - The async function to wrap
170	 * @param context - Context information for error messages
171	 * @returns A function that catches errors and returns standardized error responses
172	 */
173	export function withErrorHandling<TParams extends Record<string, unknown>>(
174		fn: (
175			args: TParams,
176			context?: ToolExecutionContext,
177		) => Promise<McpToolResponse>,
178		context: string,
179		onError?: (error: unknown, context: string, argumentKeyCount: number) => void,
180	): (
181		args: Record<string, unknown>,
182		context?: ToolExecutionContext,
183	) => Promise<McpToolResponse> {
184		return async (
185			rawArgs: Record<string, unknown>,
186			requestContext?: ToolExecutionContext,
187		) => {
188			const normalizedArgs = rawArgs ?? {};
189			try {
190				return await fn(normalizedArgs as TParams, requestContext);
191			} catch (error) {
192				try {
193					onError?.(error, context, Object.keys(normalizedArgs).length);
194				} catch {
195					console.error("MCP error observer failure", {
196						category: "ObserverError",
197					});
198				}
199	
200				return createErrorResponse(error, context);
201			}
202		};
203	}
